import * as T from './three.module.js';import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
const sharedPalette=new Map();
export function buildNeighbourBuilding(b,p){const root=new T.Group(),palette=sharedPalette,unit=new T.BoxGeometry(1,1,1);root.name=(b.kind==='house'?'Middle-class farmhouse':b.kind==='villa'?'Family estate house':b.kind)+' · '+p.name;function mat(c){if(!palette.has(c))palette.set(c,new T.MeshStandardMaterial({color:c,roughness:.84,metalness:0}));const m=palette.get(c);if(c==='#a5bfc0'||c==='#a8bfc1')m.userData.nightWindow=true;return m;}function box(w,h,d,c,x,y,z){const m=new T.Mesh(unit,mat(c));m.scale.set(w,h,d);m.position.set(x,y,z);root.add(m);return m;}
 const home=['house','villa'].includes(b.kind),h=b.h,w=b.w,d=b.d;
 box(w+.3,.35,d+.3,'#979d91',b.x,.35,b.z);box(w,h,d,home?p.color:'#b3baab',b.x,h/2+.35,b.z);for(const side of [-1,1]){const pitch=home?.38:.23,half=w/2+.6,r=box(half/Math.cos(pitch),.18,d+1.2,p.roof,b.x+side*half/2,h+.35+half*Math.tan(pitch)/2,b.z);r.rotation.z=-side*pitch;}
 if(home){for(const x of [-w*.3,w*.3]){box(2,1.5,.15,'#a5bfc0',b.x+x,h*.56,b.z+d/2+.1);for(const s of [-1,1])box(.12,1.7,.22,'#ede5cc',b.x+x+s*1.05,h*.56,b.z+d/2+.13);box(2.2,.12,.22,'#ede5cc',b.x+x,h*.56-.85,b.z+d/2+.15);box(.08,1.5,.2,'#e4e1ca',b.x+x,h*.56,b.z+d/2+.18);}
 box(1.8,2.8,.14,'#58736a',b.x,1.8,b.z+d/2+.12);box(.12,.12,.12,'#b7a56a',b.x+.6,1.7,b.z+d/2+.24);box(w*.75,.18,2.2,'#a69879',b.x,.35,b.z+d/2+1.1);box(w*.78,.16,2.4,p.roof,b.x,3.25,b.z+d/2+1);for(const side of [-1,1])box(.12,3,.12,'#e5d9bd',b.x+side*w*.35,1.8,b.z+d/2+1.9);
 for(const side of [-1,1]){box(2.2,.15,.7,'#826e52',b.x+side*w*.31,.85,b.z+d/2+1.2);for(const sx of [-.85,.85])box(.1,.6,.1,'#786a52',b.x+side*w*.31+sx,.5,b.z+d/2+1.2);}
 if(b.kind==='villa'){box(w*.45,2.2,d*.6,p.color,b.x+1,h+1.4,b.z-.5);for(const x of [-1,2])box(1.6,1.2,.15,'#a8bfc1',b.x+x,h+1.4,b.z+d*.3-.4);box(w*.5,.2,d*.7,p.roof,b.x+1,h+2.55,b.z-.5);}
 box(.9,2,.9,'#927e68',b.x-w*.3,h+1.2,b.z-d*.25);
 }else{box(w*.36,h*.7,.18,'#64766e',b.x,h*.35+.3,b.z+d/2+.12);for(let i=0;i<7;i++)box(w*.36,.035,.2,'#9ca89a',b.x,.55+i*h*.08,b.z+d/2+.15);for(const x of [-w*.35,w*.35])box(1.5,1.1,.18,'#a9bfc0',b.x+x,h*.65,b.z+d/2+.12);if(b.kind==='stable')for(const x of [-w*.3,w*.3])box(2,2.6,.2,'#72644c',b.x+x,1.65,b.z+d/2+.2);}
 root.updateMatrixWorld(true);const buckets=new Map();for(const o of [...root.children]){o.updateMatrix();const g=o.geometry.toNonIndexed().applyMatrix4(o.matrix);if(!buckets.has(o.material))buckets.set(o.material,[]);buckets.get(o.material).push(g);root.remove(o);}for(const [m,list]of buckets){const mesh=new T.Mesh(mergeGeometries(list),m);mesh.receiveShadow=true;root.add(mesh);for(const g of list)g.dispose();}return root;}
